import{_ as a,o as n,c as i,ag as r}from"./chunks/framework.cwoGUd1H.js";const m=JSON.parse('{"title":"Aufgabe - Click Game","description":"","frontmatter":{},"headers":[],"relativePath":"modul/2-html-elemente-mit-javascript-veraendern/2-5-aufgabe.md","filePath":"content/modul/2 - HTML Elemente mit Javascript verändern/2.5 - Aufgabe.md","lastUpdated":1776459490000}'),t={name:"modul/2-html-elemente-mit-javascript-veraendern/2-5-aufgabe.md"};function l(s,e,d,o,c,u){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="aufgabe-click-game" tabindex="-1">Aufgabe - Click Game <a class="header-anchor" href="#aufgabe-click-game" aria-label="Permalink to &quot;Aufgabe - Click Game&quot;">​</a></h1><p>Wir bauen Schritt für Schritt ein kleines Spiel, bei dem man auf ein Element klickt, Punkte sammelt und sich das Element bewegt.</p><h3 id="_1-player-auswahlen-und-farbe-andern" tabindex="-1">1: Player auswählen und Farbe ändern <a class="header-anchor" href="#_1-player-auswahlen-und-farbe-andern" aria-label="Permalink to &quot;1: Player auswählen und Farbe ändern&quot;">​</a></h3><p>Selektiere mit Javascript das HTML-Element mit der ID <code>player</code>. Hilfe dazu findest du in <a href="/288-javascript/modul/2-html-elemente-mit-javascript-veraendern/2-1-dom-elemente-ansprechen">2.1 - DOM Elemente ansprechen</a>.</p><p>Ändere danach die Hintergrundfarbe des Players. Hilfe dazu findest du in <a href="/288-javascript/modul/2-html-elemente-mit-javascript-veraendern/2-2-dom-elemente-veraendern">2.2 - DOM Elemente verändern</a>.</p><h3 id="_2-hintergrundfarbe-erst-bei-klick-andern" tabindex="-1">2: Hintergrundfarbe erst bei Klick ändern <a class="header-anchor" href="#_2-hintergrundfarbe-erst-bei-klick-andern" aria-label="Permalink to &quot;2: Hintergrundfarbe erst bei Klick ändern&quot;">​</a></h3><p>Die Hintergrundfarbe soll sich <strong>erst ändern, wenn man auf den Player klickt</strong>. Verwende dafür ein Click Event aus <a href="/288-javascript/modul/2-html-elemente-mit-javascript-veraendern/2-3-dom-click-events">2.3 - DOM Click Events</a>.</p><h3 id="_3-position-bei-jedem-klick-verandern" tabindex="-1">3: Position bei jedem Klick verändern <a class="header-anchor" href="#_3-position-bei-jedem-klick-verandern" aria-label="Permalink to &quot;3: Position bei jedem Klick verändern&quot;">​</a></h3><p>Bei jedem Klick soll sich der Player an eine <strong>zufällige Position</strong> bewegen.</p><p><strong>Tipps:</strong></p><ul><li>Mit <code>Math.random()</code> erhältst du eine Zufallszahl zwischen <code>0</code> und <code>1</code>.</li><li>Mit <code>playground.clientWidth</code> und <code>playground.clientHeight</code> kannst du Breite und Höhe des Spielfelds auslesen.</li><li>Verwende die Funktion <code>setPosition(element, x, y)</code>. Diese Funktion kommt aus dem BBZ-Game-Framework und setzt das Element an die Position <code>x</code> und <code>y</code>.</li></ul><p>Beispiel:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setPosition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(player, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h3 id="_4-score-hinzufugen" tabindex="-1">4: Score hinzufügen <a class="header-anchor" href="#_4-score-hinzufugen" aria-label="Permalink to &quot;4: Score hinzufügen&quot;">​</a></h3><p><strong>Ziel:</strong><br> Erstelle einen Score, der bei jedem Klick <strong>um 1 erhöht wird</strong>.</p><p><strong>Tipps:</strong></p><ul><li>Erstelle eine Variable: <code>let score = 0;</code></li><li>Verwende <code>textContent</code>, um den Score im HTML anzuzeigen. Hilfe dazu findest du in <a href="/288-javascript/modul/2-html-elemente-mit-javascript-veraendern/2-2-dom-elemente-veraendern">2.2 - DOM Elemente verändern</a>.</li></ul><h2 id="_5-bonus" tabindex="-1">5: Bonus <a class="header-anchor" href="#_5-bonus" aria-label="Permalink to &quot;5: Bonus&quot;">​</a></h2><ul><li>Ändere die Farbe bei jedem Klick zufällig 🎨</li><li>Mache das Element kleiner, je höher der Score ist</li><li>Füge einen Timer hinzu ⏱️</li></ul><hr><p>Viel Spass beim Programmieren! 🚀</p>',21)])])}const p=a(t,[["render",l]]);export{m as __pageData,p as default};
